import data from '../data/currencies.json'

export interface CurrencyMeta {
  code: string
  name: string
  /** Where the currency is issued; its inflation is measured there. */
  region: string
  flag: string
  /** IMF economy used for inflation (null: none available). */
  imf: string | null
  /** Set when inflation comes from a proxy economy, e.g. "UK CPI". */
  cpiNote?: string
}

/** Generated by scripts/fetch-fx.mjs: popular currencies first, then A–Z. */
export const CURRENCIES: readonly CurrencyMeta[] = data as CurrencyMeta[]
export const CURRENCY: Readonly<Record<string, CurrencyMeta>> = Object.fromEntries(CURRENCIES.map((c) => [c.code, c]))
export const isCurrency = (code: string): boolean => code in CURRENCY

/** How many entries at the top of CURRENCIES are the "popular" group. */
export const POPULAR_COUNT = 14
